// Public artwork (poster frames) generated by the pipeline.
import fs from "node:fs";
import { mediaPath } from "@/server/stream.ts";

export async function GET(_req: Request, ctx: { params: Promise<{ mediaId: string; file: string }> }) {
  const { mediaId, file } = await ctx.params;
  if (!/^(backdrop|thumb)\.jpg$/.test(file)) return new Response("not found", { status: 404 });
  const f = mediaPath(Number(mediaId), file);
  if (!f) return new Response("not found", { status: 404 });
  return new Response(fs.readFileSync(f), { headers: { "content-type": "image/jpeg", "cache-control": "public, max-age=86400" } });
}
